Here is an AWS Lambda function in Go that deletes EBS Snapshots based on the `backup_type` tag and the specified retention policies:
```
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	// Create an EC2 client
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Fatal(err)
	}
	ec2Client := ec2.New(sess)

	// Get a list of EBS snapshots with the "backup_type" tag
	params := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
			人物: []*string{aws.String("monthly"), aws.String("daily"), aws.String("weekly"), aws.String("yearly")},
			},
		},
	}
	snapshots, err := ec2Client.DescribeSnapshots(params)
	if err != nil {
		log.Fatal(err)
	}

	// Delete snapshots based on retention policies
	for _, snapshot := range snapshots.Snapshots {
		backupType := strings.Split(*snapshot.Tags[0].Value, ":")[1] // Get the backup type from the tag value

		switch backupType {
		case "monthly":
			// Keep the last 14 monthly snapshots
			if len(getSnapshotsOfSameBackupType(ec2Client, "monthly")) >= 14 {
				err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: aws.String(*snapshot.SnapshotId)})
				if err != nil {
					log.Fatal(err)
				}
				log.Printf("Deleted monthly snapshot: %s", *snapshot.SnapshotId)
			}
		case "daily":
			// Keep the last 10 daily snapshots
			if len(getSnapshotsOfSameBackupType(ec2Client, "daily")) >= 10 {
				err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: aws.String(*snapshot.SnapshotId)})
				if err != nil {
					log.Fatal(err)
				}
				log.Printf("Deleted daily snapshot: %s", *snapshot.SnapshotId)
			}
		case "weekly":
			// Keep the last 4 weekly snapshots
			if len(getSnapshotsOfSameBackupType(ec2Client, "weekly")) >= 4 {
				err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: aws.String(*snapshot.SnapshotId)})
				if err != nil {
					log.Fatal(err)
				}
				log.Printf("Deleted weekly snapshot: %s", *snapshot.SnapshotId)
			}
		case "yearly":
			// Keep only 1 yearly snapshot
			err := ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: aws.String(*snapshot.SnapshotId)})
			if err != nil {
				log.Fatal(err)
			}
			log.Printf("Deleted yearly snapshot: %s", *snapshot.SnapshotId)
		}
	}

	return nil, nil
}

func getSnapshotsOfSameBackupType(ec2Client *ec2.EC2, backupType string) []*ec2.Snapshot {
	params := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
				Value: []*string{aws.String(backupType)},
			},
		},
	}
	snapshots, err := ec2Client.DescribeSnapshots(params)
	if err != nil {
		log.Fatal(err)
	}

	return snapshots.Snapshots
}

func main() {
	lambda.Start(handler)
}
```
